def pos(fr):
    out=[]
    for n in fr.segmentation['nodes']:
        if n['color'] in ('N','W','B'):
            b=n['boundary']
            out.append((n['color'], n['pixels'], min(p[0] for p in b), max(p[0] for p in b), min(p[1] for p in b), max(p[1] for p in b)))
    return out

